# install.packages(c("car", "ggplot2", "rstatix", "lme4", "lmerTest"))

# 
library(ggplot2)

# 
# ---- Part 1: Processing speed across the lifespan ------------------------------
# 
# Norms for the Symbol Digit Modalities Test (SDMT) are split by age, because
# processing speed is not a straight line: it rises through adolescence, peaks in
# early adulthood and then declines.
# 
sdmt <- read.csv("data/sdmt-age.csv")
head(sdmt)

ggplot(sdmt, aes(x = age, y = sdmt)) +
  geom_point() +
  geom_smooth(method = "lm", se = FALSE) +
  labs(x = "Age (years)", y = "SDMT (correct in 90 s)")

# 
# ---- Step 1: A straight line, then a curve -------------------------------------
# 
# `I(age^2)` adds age squared as a second predictor. A negative coefficient for it
# means an inverted U.
# 
lm_lin  <- lm(sdmt ~ age, data = sdmt)
lm_quad <- lm(sdmt ~ age + I(age^2), data = sdmt)
summary(lm_lin)
summary(lm_quad)

anova(lm_lin, lm_quad) # does the curve explain more than the line?

# 
par(mfrow = c(2, 2))
plot(lm_lin)  # the U in "Residuals vs Fitted" shows the line is wrong
plot(lm_quad)
dev.off()

# 
# ---- Step 2: Centering ---------------------------------------------------------
# 
# With raw age, the intercept is the predicted score at age 0, which nobody is.
# Centering makes it the score at the mean age, and the linear coefficient becomes
# the slope there.
# 
sdmt$age_c <- sdmt$age - mean(sdmt$age)
lm_quad_c <- lm(sdmt ~ age_c + I(age_c^2), data = sdmt)
summary(lm_quad_c)

# 
# ---- Part 2: Memory after traumatic brain injury -------------------------------
# 
# Patients with traumatic brain injury (TBI) recall fewer words than controls. But
# people differ in ability before the injury, so we adjust for premorbid IQ,
# estimated from a word-reading test.
# 
tbi <- read.csv("data/tbi-memory.csv")
tbi$group <- factor(tbi$group, levels = c("Control", "TBI"))
head(tbi)

ggplot(tbi, aes(x = premorbid_iq, y = recall, colour = group)) +
  geom_point() +
  geom_smooth(method = "lm", se = FALSE) +
  labs(x = "Premorbid IQ", y = "RAVLT delayed recall (words)")

# 
# ---- Step 1: ANOVA, then ANCOVA ------------------------------------------------
# 
# Put the covariate first. In the ANCOVA, the `groupTBI` coefficient is the
# difference between groups for people with the same premorbid IQ.
# 
aov_anova  <- aov(recall ~ group, data = tbi)
aov_ancova <- aov(recall ~ premorbid_iq + group, data = tbi)
summary.lm(aov_anova)
summary.lm(aov_ancova)
car::Anova(aov_ancova, type = 2)

anova(aov_anova, aov_ancova) # does the covariate improve the model?

# 
# The covariate barely moves the group difference here, because the groups have
# similar IQs. What it does is shrink the residual error, so the group effect is
# estimated more precisely: compare the two standard errors for `groupTBI`.
# 
# ---- Step 2: Assumptions -------------------------------------------------------
# 
# ANCOVA assumes the same slope in both groups. Test it by adding the interaction:
# if it is not significant, the additive model is fine.
# 
par(mfrow = c(2, 2))
plot(aov_ancova)
dev.off()

# 
car::leveneTest(recall ~ group, data = tbi)
anova(aov_ancova, aov(recall ~ premorbid_iq * group, data = tbi)) # equal slopes?

# 
# ---- Part 3: Cognitive reserve -------------------------------------------------
# 
# White-matter lesions on MRI go with worse cognition. The cognitive reserve
# hypothesis says that people with more education cope better with the same
# damage. If so, the slope of MoCA on lesion volume should be flatter for them:
# education *moderates* the effect of lesions.
# 
reserve <- read.csv("data/reserve-moca.csv")
reserve$education <- factor(reserve$education, levels = c("Low", "High"))
head(reserve)

ggplot(reserve, aes(x = lesion_ml, y = moca, colour = education)) +
  geom_point() +
  geom_smooth(method = "lm", se = FALSE) +
  labs(x = "White-matter lesion volume (mL)", y = "MoCA (0-30)")

# 
# ---- Step 1: From ANOVA to moderation ------------------------------------------
# 
# `lesion_ml * education` is short for `lesion_ml + education + lesion_ml:education`.
# The interaction coefficient is how much flatter (or steeper) the slope is in the
# high-education group.
# 
m_anova  <- lm(moca ~ education, data = reserve)
m_ancova <- lm(moca ~ lesion_ml + education, data = reserve)
m_mod    <- lm(moca ~ lesion_ml * education, data = reserve)
summary(m_mod)

anova(m_anova, m_ancova, m_mod) # each step adds a term

# 
# ---- Step 2: Centering and type III tests --------------------------------------
# 
# `educationHigh` is the group difference at 0 mL of lesions, outside the data.
# Centering moves it to the average lesion volume. With an interaction, use
# deviation coding and type III sums of squares.
# 
m_mod_c <- lm(moca ~ scale(lesion_ml, scale = FALSE) * education,
              contrasts = list(education = "contr.sum"),
              data = reserve)
summary(m_mod_c)
car::Anova(m_mod_c, type = 3)

# 
par(mfrow = c(2, 2))
plot(m_mod)
dev.off()

# 
# ---- Part 4: Working-memory training after stroke ------------------------------
# 
# Stroke patients were randomised to computerised working-memory training or usual
# care, and did a digit span test at three visits. Group varies between patients
# and visit within them. The question is the interaction: do the two groups change
# differently over time?
# 
stroke <- read.csv("data/stroke-training.csv")
stroke$patient <- factor(stroke$patient)
stroke$group   <- factor(stroke$group, levels = c("UsualCare", "Training"))
stroke$visit   <- factor(stroke$visit, levels = c("Baseline", "Post", "FollowUp"))
head(stroke)

tapply(stroke$digit_span, list(stroke$group, stroke$visit), mean)

ggplot(stroke, aes(x = visit, y = digit_span, colour = group, group = group)) +
  stat_summary(fun = mean, geom = "point", size = 3) +
  stat_summary(fun = mean, geom = "line") +
  stat_summary(fun.data = mean_se, geom = "errorbar", width = 0.1) +
  labs(x = "Visit", y = "Digit span (mean ± SE)")

# 
# ---- Step 1: Mixed-design ANOVA ------------------------------------------------
# 
summary(aov(digit_span ~ group * visit + Error(patient/visit), data = stroke))

# same analysis, with Mauchly's test of sphericity
rstatix::anova_test(data = stroke, dv = digit_span, wid = patient,
                    between = group, within = visit)

# 
# ---- Step 2: Mixed-effects model -----------------------------------------------
# 
# With dummy coding, the intercept is the usual-care group at baseline, and each
# interaction coefficient is the extra change in the training group at that visit.
# 
library(lmerTest) # loads lme4 and adds p-values

lmer_mod <- lmer(digit_span ~ group * visit + (1 | patient), data = stroke)
summary(lmer_mod)

# deviation coding for type III tests, as in the ANOVA above
lmer_mod_sum <- lmer(digit_span ~ group * visit + (1 | patient),
                     contrasts = list(group = "contr.sum", visit = "contr.sum"),
                     data = stroke)
anova(lmer_mod_sum)

